Given an array arr[] and an integer k , find the length of the smallest subarray whose Greatest Common Divisor equals k.Note: If no such subarray exists, return -1.Examples:Input: arr[] = [6, 9, 7, 10, 12, 24, 36, 27], k = 3Output: 2Explanation: GCD of subarray {6,9} is 3. GCD of subarray {24, 36, 27} is also 3,but {6, 9} is the smallest.Input: arr[] = [9, 12, 15, 24, 36, 27], k = 2Output: -1Explanation: GCD 2 is not possible from any subarray from the given array.Input: arr[] = [1, 2, 4, 8], k = 1Output: 1Try It Yourself[Naive Approach] Nested Loop with GCD - O(n² log M) Time and O(1) SpaceThe idea is based on the fact that adding more elements to a subarray never increases overall GCD.For each starting index, extend subarray and track GCD. If GCD becomes less than k, break early. If GCD equals k, update minimum length.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Function to compute GCD of two numbers
int findGCD(int a, int b) {
    if (b == 0)
        return a;
    return findGCD(b, a % b);
}

// Function to find the minimum length of subarray
// whose GCD is exactly k
int findSmallestSubArr(vector<int>& arr, int k) {

    int n = arr.size();
    int minLen = n + 1;

    // Iterate over all possible subarrays
    for (int i = 0; i < n; i++) {

        int currGCD = 0;

        for (int j = i; j < n; j++) {

            // Update GCD of current subarray
            currGCD = findGCD(currGCD, arr[j]);

            // If current GCD becomes less than k, break early
            if (currGCD < k)
                break;

            // If GCD equals k, update minLen
            if (currGCD == k) {
                minLen = min(minLen, j - i + 1);
                break;
            }
        }
    }

    // If no valid subarray found, return -1
    return (minLen == n + 1) ? -1 : minLen;
}

int main() {

    vector<int> arr = {6, 9, 7, 10, 12, 24, 36, 27};
    int k = 3;

    cout << findSmallestSubArr(arr, k) << endl;

    return 0;
}


